function downloadBlob(bytes,type,name){const url=URL.createObjectURL(new Blob([bytes],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function labPage(){const savedDraft=workStore.read('diagram',null,raw=>cleanDraft(raw));const importingCode=carriedCode!==null;view.innerHTML=crumb('Diagram lab')+`<div class="lab-header"><p class="eyebrow">FROM ALGORITHM TO PICTURE</p><h1>See the logic take shape.</h1><p class="lede">Convert the documented pseudocode syntax into a flowchart or a module call hierarchy. Processing happens in your browser; no AI API is used.</p></div><div class="lab-controls"><label class="field-label">Load an example<select id="lab-example">${Object.keys(samples).map(s=>`<option>${e(s)}</option>`).join('')}</select></label><label class="field-label">Diagram type<select id="lab-type"><option value="flow">Flowchart</option><option value="hierarchy">Module hierarchy</option></select></label></div><div class="lab-grid"><section class="panel"><h2>Your pseudocode</h2><label class="field-label" for="pseudocode">Edit the algorithm<textarea id="pseudocode" class="editor" spellcheck="false" maxlength="100000">${e(carriedCode??savedDraft?.code??samples['Pass or revise'])}</textarea></label><div class="button-row"><button class="button" id="generate-chart">Generate diagram</button><button class="button secondary" id="trace-my-code">Trace this code</button></div><p class="status" id="lab-status" role="status"></p><label class="field-label">Flowchart section<select id="lab-module"><option value="main">Main program</option></select></label></section><section class="panel"><h2>Your diagram</h2><div class="diagram-toolbar"><button class="button secondary" id="download-svg" disabled>Download SVG</button><button class="button secondary" id="download-png" disabled>Download PNG</button><button class="button secondary" id="diagram-pdf" disabled>Print / PDF</button><button class="button secondary" id="fit-chart" disabled>Fit width</button></div><div id="lab-diagram" class="diagram"><div class="diagram-placeholder"><span>◇</span><p>Your diagram will appear here.<br>Choose an example and generate it.</p></div></div></section></div><details class="syntax panel"><summary>Supported syntax and limits</summary><p>The converter checks recognised statements and matching block boundaries. It does not execute expressions, validate types or prove that an algorithm is correct. Keywords are case-insensitive. Use one statement per line.</p><div class="scroll-table"><table><thead><tr><th>Structure</th><th>Notation</th></tr></thead><tbody><tr><td>Program</td><td><code>BEGIN</code> ... <code>END</code></td></tr><tr><td>Input and output</td><td><code>INPUT name</code> / <code>OUTPUT "Hello", name</code></td></tr><tr><td>Assignment and declaration</td><td><code>SET total = total + value</code> / <code>DECLARE total AS REAL</code></td></tr><tr><td>Selection</td><td><code>IF condition THEN</code> ... <code>ELSE</code> ... <code>ENDIF</code>. Use ELSEIF condition THEN for additional branches, or nest IF inside ELSE.</td></tr><tr><td>Counted loop</td><td><code>FOR i = 1 TO 5 STEP 1</code> ... <code>ENDFOR</code>. STEP must be a nonzero integer; it defaults to 1.</td></tr><tr><td>Conditional loops</td><td><code>WHILE condition DO</code> ... <code>ENDWHILE</code> / <code>REPEAT</code> ... <code>UNTIL condition</code></td></tr><tr><td>CASE</td><td><code>CASE expression OF</code>, <code>WHEN value:</code>, <code>OTHERWISE:</code>, <code>ENDCASE</code>. Displayed as equivalent chained decisions.</td></tr><tr><td>Methods</td><td><code>METHOD name(parameters)</code> ... <code>ENDMETHOD</code> , <code>MODULE name(parameters)</code> ... <code>ENDMODULE</code> or <code>FUNCTION name(parameters) RETURNS REAL</code> ... <code>ENDFUNCTION</code>. Define methods outside BEGIN/END.</td></tr><tr><td>Calls and returns</td><td><code>CALL name(arguments)</code>. Hierarchy view also recognises defined function names inside expressions. RETURN creates a terminal exit in a flowchart. Select a method in the section selector to inspect its body.</td></tr><tr><td>Comments</td><td>Use <code>//</code> for whole-line or inline comments outside quoted strings. Maximum 1,000 non-empty lines, 100,000 characters and 16 levels of nesting protect browser responsiveness.</td></tr></tbody></table></div><p>Also accepted: PRINT/DISPLAY, READ, START/STOP, END IF, ELSE IF, plain assignments using = or arrows, FOR ... FROM ... TO, NEXT and WEND. There is no quota or payment per diagram. Structured syntax and browser safety limits still apply.</p><p>Hierarchy charts show call relationships, including recursion; uncalled methods are shown separately. Undefined calls are reported. SWITCH / CASE is accepted as an alias for CASE ... OF, WHEN and OTHERWISE. Class syntax, overload resolution, BREAK and CONTINUE are not supported in this release. Use the class diagrams in Unit 5 for object-oriented examples.</p></details>`;sidebar();
 const editor=$('#pseudocode'),type=$('#lab-type'),module=$('#lab-module'),status=$('#lab-status');currentSVG='';lastAst=null;if(!importingCode&&savedDraft)type.value=savedDraft.type;module.disabled=type.value==='hierarchy';carriedCode=null;
 function persistLab(){workStore.write('diagram',{code:editor.value,type:type.value});}if(importingCode)persistLab();
 function invalidate(){currentSVG='';lastAst=null;['download-svg','download-png','diagram-pdf','fit-chart'].forEach(id=>$('#'+id).disabled=true);$('#lab-diagram').innerHTML='<div class="diagram-placeholder"><span>◇</span><p>Your code has changed. Generate a fresh diagram.</p></div>';status.textContent='';}
 function draw(){try{lastAst=parse(editor.value);const selected=module.value;module.innerHTML='<option value="main">Main program</option>'+lastAst.modules.map(m=>`<option value="${e(m.name)}">${e(m.name)}</option>`).join('');if([...module.options].some(o=>o.value===selected))module.value=selected;let notice='';if(type.value==='hierarchy'){const result=hierarchy(lastAst);currentSVG=result.svg;if(result.missing.length)notice=' Undefined calls: '+result.missing.join(', ')+'. These are shown without a definition.';}else currentSVG=flowchart(lastAst,module.value);$('#lab-diagram').innerHTML=currentSVG;$('#lab-diagram').classList.remove('fit');$('#fit-chart').textContent='Fit width';status.textContent='Diagram generated from the supported syntax.'+notice;module.disabled=type.value==='hierarchy';['download-svg','download-png','diagram-pdf','fit-chart'].forEach(id=>$('#'+id).disabled=false);}catch(err){currentSVG='';$('#lab-diagram').innerHTML='<div class="diagram-placeholder"><span>!</span><p>Check the editor feedback, correct the code and try again.</p></div>';status.textContent=err.message;['download-svg','download-png','diagram-pdf','fit-chart'].forEach(id=>$('#'+id).disabled=true);}}
 $('#lab-example').onchange=event=>{editor.value=samples[event.target.value];type.value=event.target.value==='Module hierarchy'?'hierarchy':'flow';module.value='main';invalidate();persistLab();};editor.oninput=()=>{invalidate();persistLab();};type.onchange=()=>{module.disabled=type.value==='hierarchy';invalidate();persistLab();};$('#generate-chart').onclick=draw;$('#trace-my-code').onclick=()=>{carriedTraceCode=editor.value;location.hash='trace';};module.onchange=draw;
 $('#download-svg').onclick=()=>{if(currentSVG)downloadBlob(currentSVG,'image/svg+xml','LogicLab-diagram.svg')};$('#fit-chart').onclick=()=>{const fit=$('#lab-diagram').classList.toggle('fit');$('#fit-chart').textContent=fit?'Actual size':'Fit width';};
 $('#download-png').onclick=async()=>{if(!currentSVG)return;const button=$('#download-png');button.disabled=true;try{const svg=currentSVG;const img=new Image(),url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml'}));try{await new Promise((res,rej)=>{img.onload=res;img.onerror=rej;img.src=url});const scale=Math.min(2,6000/img.width,10000/img.height,Math.sqrt(18000000/(img.width*img.height)));const canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);const blob=await new Promise(r=>canvas.toBlob(r,'image/png'));if(!blob)throw Error();downloadBlob(blob,'image/png','LogicLab-diagram.png');status.textContent='PNG prepared. Check your downloads.';}finally{URL.revokeObjectURL(url)}}catch{status.textContent='PNG could not be created. Try the SVG download instead.';}finally{button.disabled=!currentSVG;}};
 $('#diagram-pdf').onclick=()=>{if(!currentSVG)return;document.body.classList.add('print-diagram');window.print();};window.onafterprint=()=>document.body.classList.remove('print-diagram');}
function traceData(kind){if(kind==='sum'){let states=[{line:1,vars:{total:0,i:'-'},output:'',note:'Initialise total before the loop.'}];let total=0;for(let i=1;i<=3;i++){states.push({line:2,vars:{total,i},output:'',note:`The loop condition is true for i = ${i}.`});total+=i;states.push({line:3,vars:{total,i},output:'',note:`Add ${i} to the running total.`})}states.push({line:2,vars:{total,i:4},output:'',note:'i is now 4. The upper bound is 3, so the loop ends.'},{line:5,vars:{total,i:4},output:String(total),note:'Display the final total after the loop.'});return{code:'SET total = 0\nFOR i = 1 TO 3\n  SET total = total + i\nENDFOR\nOUTPUT total',states};}
 if(kind==='search'){const a=[8,3,11,5],states=[{line:1,vars:{i:0,foundAt:-1},array:a,compare:[],output:'',note:'Search for 11. Initialise the result to -1.'}];for(let i=0;i<a.length;i++){states.push({line:3,vars:{i,foundAt:i>2?2:-1},array:a,compare:[i],output:'',note:`Compare values[${i}] (${a[i]}) with 11.`});if(a[i]===11)states.push({line:4,vars:{i,foundAt:i},array:a,compare:[i],output:'',note:'A match is found at index 2. Store its position.'});}states.push({line:7,vars:{i:4,foundAt:2},array:a,compare:[],output:'2',note:'The full traversal is complete. Display the match position.'});return{code:'SET foundAt = -1\nFOR i = 0 TO 3\n  IF values[i] = 11 THEN\n    SET foundAt = i\n  ENDIF\nENDFOR\nOUTPUT foundAt',states};}
 const a=[5,2,4,1],states=[{line:1,vars:{pass:0,j:'-'},array:[...a],compare:[],output:'',note:'Start with four unsorted values.'}];for(let p=0;p<a.length-1;p++)for(let j=0;j<a.length-1-p;j++){states.push({line:3,vars:{pass:p,j},array:[...a],compare:[j,j+1],output:'',note:`Compare adjacent values ${a[j]} and ${a[j+1]}.`});if(a[j]>a[j+1]){[a[j],a[j+1]]=[a[j+1],a[j]];states.push({line:6,vars:{pass:p,j},array:[...a],compare:[j,j+1],output:'',note:'Swap the pair using a temporary value.'})}}states.push({line:10,vars:{pass:3,j:'-'},array:[...a],compare:[],output:a.join(', '),note:'The array is now sorted in ascending order.'});return{code:'FOR pass = 0 TO 2\n  FOR j = 0 TO 2 - pass\n    IF values[j] > values[j + 1] THEN\n      SET temp = values[j]\n      SET values[j] = values[j + 1]\n      SET values[j + 1] = temp\n    ENDIF\n  ENDFOR\nENDFOR\nOUTPUT values',states};}
function tracePage(){interactiveTracePage({view,crumb,sidebar,initialCode:carriedTraceCode,openDiagram:code=>{carriedCode=code;location.hash='lab';}});carriedTraceCode=null;}
function guidedTracePage(){view.innerHTML=crumb('Visual step-through')+`<p class="eyebrow">WATCH THE PROGRAM STATE</p><h1>Slow it down. See every change.</h1><p class="lede">These guided traces use fixed examples. They do not execute arbitrary pasted pseudocode.</p><label class="field-label" style="max-width:400px">Choose an algorithm<select id="trace-example"><option value="sum">A loop and a running total</option><option value="search">Linear search in an array</option><option value="sort">Bubble sort, one comparison at a time</option></select></label><div id="trace-view"></div>`;sidebar();let step=0,data=traceData('sum');function render(){const s=data.states[step];$('#trace-view').innerHTML=`<div class="trace-grid"><section class="panel"><h2>The algorithm</h2><pre><code>${data.code.split('\n').map((line,i)=>`<span class="line-code ${i+1===s.line?'trace-current':''}"><span class="ln">${i+1}</span>${e(line)}</span>`).join('')}</code></pre><div class="button-row"><button class="button secondary" id="trace-prev" ${step===0?'disabled':''}>Previous step</button><button class="button" id="trace-next" ${step===data.states.length-1?'disabled':''}>Next step</button><button class="button secondary" id="trace-reset">Restart</button></div><p class="status" role="status">Step ${step+1} of ${data.states.length}</p></section><section class="panel"><h2>Current state</h2><div class="trace-variables">${Object.entries(s.vars).map(([key,value])=>`<div class="variable"><span>${e(key)}</span><strong>${e(value)}</strong></div>`).join('')}</div>${s.array?`<div class="array-cells">${s.array.map((v,i)=>`<div class="array-cell ${s.compare.includes(i)?'compare':''}"><small style="font-size:9px;display:block;color:#87909c">[${i}]</small>${v}</div>`).join('')}</div>`:''}<p class="trace-description" role="status">${e(s.note)}</p><h3 style="font-size:12px">Output</h3><div class="trace-output">${e(s.output||'No output yet')}</div><h3 style="font-size:12px;margin-top:25px">Trace history</h3><div class="scroll-table"><table class="trace-history"><thead><tr><th>Step</th><th>Line</th><th>Variables</th></tr></thead><tbody>${data.states.slice(0,step+1).map((t,i)=>`<tr><td>${i+1}</td><td>${t.line}</td><td>${e(Object.entries(t.vars).map(([k,v])=>k+' = '+v).join(', '))}</td></tr>`).join('')}</tbody></table></div></section></div>`;$('#trace-prev').onclick=()=>{step--;render()};$('#trace-next').onclick=()=>{step++;render()};$('#trace-reset').onclick=()=>{step=0;render()};}$('#trace-example').onchange=event=>{data=traceData(event.target.value);step=0;render()};render();}
const libraryWork=new Map();
let taskFilters={query:'',topic:'All topics',level:'All levels'};
function libraryState(id){if(!libraryWork.has(id))libraryWork.set(id,workStore.read('task:'+id,cleanTask({}),cleanTask));return libraryWork.get(id);}
function tasksPage(){
 view.innerHTML=crumb('Practice tasks')+`<p class="eyebrow">YOUR SPACE TO PRACTISE</p><h1>Small tasks. Stronger understanding.</h1><p class="lede">Choose a topic, try a question, then compare your thinking with a model solution. These 53 library tasks extend the 44 tasks inside your lessons.</p><div class="button-row"><a class="button secondary" href="#activities">Try interactive exercises</a><a class="button secondary" href="#resources">Download questions and answers</a></div><div class="task-filters panel"><label class="field-label">Search tasks<input id="task-search" type="search" placeholder="Try average, array or method" value="${e(taskFilters.query)}"></label><label class="field-label">Topic<select id="task-topic">${['All topics',...new Set(taskBank.map(t=>t.topic))].map(x=>`<option ${x===taskFilters.topic?'selected':''}>${e(x)}</option>`).join('')}</select></label><label class="field-label">Difficulty<select id="task-level">${['All levels','Foundation','Developing','Challenge'].map(x=>`<option ${x===taskFilters.level?'selected':''}>${x}</option>`).join('')}</select></label><button class="button secondary" id="clear-filters">Clear filters</button></div><p class="task-count" id="task-count" role="status"></p><div class="task-grid" id="task-results"></div><div class="note">Work at your own pace. Written answers are self-checked, not automatically graded. Drafts save automatically in this browser when storage is available. Use Saved work to review or clear them.</div>`;
 function results(){const query=taskFilters.query.trim().toLowerCase();const list=taskBank.filter(t=>(taskFilters.topic==='All topics'||t.topic===taskFilters.topic)&&(taskFilters.level==='All levels'||t.level===taskFilters.level)&&(!query||[t.title,t.prompt,t.topic].join(' ').toLowerCase().includes(query)));$('#task-count').textContent=`${list.length} ${list.length===1?'task':'tasks'} found`;$('#task-results').innerHTML=list.length?list.map(t=>`<article class="task-card"><div class="task-badges"><span class="topic-badge">${e(t.topic)}</span><span class="level-badge ${t.level.toLowerCase()}">${e(t.level)}</span></div><h2>${e(t.title)}</h2><p>${e(t.prompt)}</p><div class="task-card-bottom"><span>${t.diagram?'Diagram-ready pseudocode':'Written practice'}</span><a class="button secondary" href="#task/${t.id}">Try task</a></div></article>`).join(''):'<div class="panel empty-state"><h2>No matching tasks</h2><p>Try another keyword or clear the filters to see every task.</p></div>';}
 $('#task-search').oninput=event=>{taskFilters.query=event.target.value;results();};$('#task-topic').onchange=event=>{taskFilters.topic=event.target.value;results();};$('#task-level').onchange=event=>{taskFilters.level=event.target.value;results();};$('#clear-filters').onclick=()=>{taskFilters={query:'',topic:'All topics',level:'All levels'};$('#task-search').value='';$('#task-topic').value='All topics';$('#task-level').value='All levels';results();};results();sidebar();}
function taskPage(id){const t=taskBank.find(t=>t.id===id);if(!t){location.hash='tasks';return;}const s=libraryState(id);
 view.innerHTML=crumb('Practice / '+t.topic)+`<div class="resource-links"><a class="text-link" href="#tasks">Back to task library</a><a class="text-link" href="#resources">Download study packs</a></div><div class="task-badges" style="margin-top:22px"><span class="topic-badge">${e(t.topic)}</span><span class="level-badge ${t.level.toLowerCase()}">${e(t.level)}</span></div><h1>${e(t.title)}</h1><p class="lede">${e(t.prompt)}</p><div class="task-workspace"><section class="panel"><p class="eyebrow">1. WRITE YOUR ATTEMPT</p><h2>Think it through</h2><p>Write pseudocode, a trace or an explanation as requested. Include at least one test case.</p><form id="library-form"><label class="field-label" for="library-answer">Your answer</label><textarea class="editor" id="library-answer" spellcheck="false" required minlength="20" maxlength="20000" placeholder="Start your answer here...">${e(s.work)}</textarea><div class="button-row"><button class="button" type="submit">Submit my attempt</button>${t.diagram?'<button class="button secondary" type="button" id="library-lab">Open my code in diagram lab</button>':''}<button class="button ghost" type="button" id="copy-work">Copy my answer</button></div><p class="feedback" id="library-status" role="status">${s.attempted?'Attempt recorded. You can now reveal and compare the model solution.':''}</p></form></section><section class="panel solution-panel"><p class="eyebrow">2. COMPARE AND IMPROVE</p><h2>Model solution</h2><p>Try the task before revealing the answer. There can be more than one correct solution.</p><button class="button secondary" id="library-reveal" ${s.attempted?'':'disabled'}>Reveal model solution</button><p class="solution-lock" id="solution-lock" ${s.attempted?'hidden':''}>Submit a meaningful attempt of at least 20 characters to unlock this solution.</p><div id="library-solution" ${s.revealed?'':'hidden'}>${codeBlock(t.solution)}<h3>Check your reasoning</h3><ul>${t.checklist.map(c=>`<li>${e(c)}</li>`).join('')}</ul></div><div class="note">Self-check practice: the system does not automatically mark free-text answers or prove your algorithm correct. Drafts save in this browser when storage is available. They do not sync across devices.</div></section></div>`;
 $('#library-answer').oninput=event=>{s.work=event.target.value;workStore.write('task:'+id,cleanTask(s));};$('#library-form').onsubmit=event=>{event.preventDefault();s.work=$('#library-answer').value;const answer=s.work.trim();if(answer.length<20||!/[a-z]{3}/i.test(answer)){$('#library-status').textContent='Add a meaningful explanation or pseudocode of at least 20 characters first.';return;}s.attempted=true;workStore.write('task:'+id,cleanTask(s));$('#library-reveal').disabled=false;$('#solution-lock').hidden=true;$('#library-status').textContent='Attempt recorded. Reveal the model solution and compare your approach, bounds and test cases.';};$('#library-reveal').onclick=()=>{if(!s.attempted)return;s.revealed=true;workStore.write('task:'+id,cleanTask(s));$('#library-solution').hidden=false;};if($('#library-lab'))$('#library-lab').onclick=()=>{s.work=$('#library-answer').value;if(!s.work.trim()){$('#library-status').textContent='Write some pseudocode first, then open it in the lab.';return;}carriedCode=s.work;location.hash='lab';};$('#copy-work').onclick=async()=>{try{await navigator.clipboard.writeText($('#library-answer').value);$('#library-status').textContent='Answer copied. Paste it into your own notes to keep it.';}catch{$('#library-answer').select();$('#library-status').textContent='Select and copy your answer using your device copy command.';}};sidebar();}
function resourcesPage(){
 view.innerHTML=crumb('Downloads')+`<p class="eyebrow">LEARN ONLINE OR TAKE IT WITH YOU</p><h1>Your study resources.</h1><p class="lede">Download editable Word practice packs, printable PDFs and a teaching PowerPoint for each learning unit. Use the same exercise numbers to match questions with answers.</p><section class="panel download-panel"><h2>Practice question and answer packs</h2><p>229 exercises: 110 quiz questions, 22 debugging challenges, 44 lesson tasks and 53 task-library exercises. Includes arrays, parallel arrays, IF/ELSE and SWITCH/CASE.</p><form id="download-pack"><div class="download-controls"><label class="field-label">What would you like?<select id="pack-content"><option value="questions">Questions only</option><option value="questions-and-answers">Questions and answers</option><option value="answers">Answers only</option></select></label><label class="field-label">File format<select id="pack-format"><option value="pdf">PDF (.pdf)</option><option value="docx">Word (.docx)</option></select></label><a id="pack-download" class="button" href="./downloads/logiclab-questions.pdf" download>Download questions PDF</a></div></form><p class="note">These are open revision downloads. Answer packs are available directly. If you want to test yourself first, choose Questions only. Written solutions are examples and other correct approaches may exist.</p></section><div class="section-heading"><h2>Learning unit slides</h2><p>Editable PowerPoint (.pptx)</p></div><p class="resource-intro">The detailed decks cover all lesson theory in each unit, definitions before use, declared variables, numbered pseudocode walkthroughs, step-by-step traces and worked exercise solutions. Each unit also has a short 10-slide revision deck with key definitions, worked examples, practice answers and common mistakes. Unit 2 includes IF/ELSE and SWITCH/CASE. Unit 3 includes single and two-dimensional arrays as well as parallel arrays.</p><div class="slides-grid">${units.map(u=>`<article class="panel slide-download"><p class="eyebrow">LEARNING UNIT ${u.id}</p><h3>${e(u.title)}</h3><p>${e(u.subtitle)}</p><ul>${u.themes.map(t=>`<li>${e(t)}</li>`).join('')}</ul><a class="button secondary" href="./downloads/logiclab-unit-${u.id}.pptx?v=15" download>Download detailed Unit ${u.id} slides</a><a class="button secondary" href="./downloads/logiclab-unit-${u.id}-revision.pptx?v=15" download>Download Unit ${u.id} revision slides</a><small>Revision: 10 slides. Editable PowerPoint.</small></article>`).join('')}</div><div class="note">PowerPoint files can be opened in PowerPoint or compatible presentation software. Downloads work without an account. This is supplementary practice material.</div>`;
 function update(){const content=$('#pack-content').value,format=$('#pack-format').value,label=content==='questions'?'questions':content==='answers'?'answers':'questions and answers';$('#pack-download').href='./downloads/logiclab-'+content+'.'+format;$('#pack-download').textContent='Download '+label+' '+(format==='docx'?'Word':'PDF');}$('#pack-content').onchange=update;$('#pack-format').onchange=update;$('#download-pack').onsubmit=event=>event.preventDefault();sidebar();}
function savedWorkPage(){
 const entries=workStore.list().map(item=>{let title,href;if(item.key==='exam'){title='PRLD practice exam';href='#exams';}else if(item.key==='diagram'){title='Diagram lab draft';href='#lab';}else if(item.key==='tracer'){title='Interactive tracing draft';href='#trace';}else if(item.key.startsWith('lesson:')){const l=lessons.find(x=>x.id===item.key.slice(7));if(l){title=l.title;href='#lesson/'+l.id;}}else if(item.key.startsWith('task:')){const t=taskBank.find(x=>x.id===item.key.slice(5));if(t){title=t.title;href='#task/'+t.id;}}else if(item.key.startsWith('activity:')){const a=activities.find(x=>x.id===item.key.slice(9));if(a){title=a.title;href='#activity/'+a.id;}}return title?{...item,title,href}:null;}).filter(Boolean);
 view.innerHTML=crumb('Saved work')+`<p class="eyebrow">CONTINUE WHERE YOU LEFT OFF</p><h1>Your saved work</h1><p class="lede">Drafts and question progress save on this browser profile. They are shared by anyone using this same profile, and do not sync to another device. Private browsing, clearing site data or browser storage limits can remove or prevent saving.</p><p>Tracer code is saved as a draft. Enter inputs and prepare a fresh run after reopening. Runtime inputs and trace history are not saved.</p><div class="panel"><h2>Saved items</h2>${entries.length?`<div class="saved-work-list">${entries.map(item=>`<article><div><h3>${e(item.title)}</h3><p>${item.unreadable?'This saved item could not be read.':item.updatedAt?'Last saved: '+e(new Date(item.updatedAt).toLocaleString()):'Saved date unavailable'}</p></div><a class="button secondary" href="${e(item.href)}">Continue</a></article>`).join('')}</div>`:'<p>No saved drafts or question attempts yet. Start an exercise or type in an editor, then return here.</p>'}</div><section class="panel saved-work-controls"><h2>Clear saved work</h2><p>This removes drafts, exercise answers, quiz progress and saved hints from this browser. Completed-lesson marks are kept. Use Reset my progress in the sidebar to reset those separately.</p><button class="button secondary" id="clear-saved-work">Clear saved work</button><p id="clear-work-status" role="status"></p></section><dialog id="clear-work-dialog" aria-labelledby="clear-work-title"><h2 id="clear-work-title">Remove all saved work?</h2><p>This removes this site's saved drafts and question progress in the current browser profile. Completed-lesson marks remain. Copy any work you want to keep first.</p><div class="button-row"><button class="button secondary" id="cancel-clear-work">Keep saved work</button><button class="button danger" id="confirm-clear-work">Remove saved work</button></div></dialog>`;
 $('#clear-saved-work').onclick=()=>$('#clear-work-dialog').showModal();$('#cancel-clear-work').onclick=()=>$('#clear-work-dialog').close();$('#confirm-clear-work').onclick=()=>{if(workStore.clearAll())location.reload();else{$('#clear-work-dialog').close();$('#clear-work-status').textContent='Some saved work could not be removed. Try again after checking browser storage settings.';}};sidebar();
}
function about(){view.innerHTML=crumb('About & privacy')+`<p class="eyebrow">LOGICLAB / FIRST RELEASE</p><h1>Built to make the logic clearer.</h1><div class="panel theory"><h2>About the course</h2><p>LogicLab is an independent supplementary learning platform by Lefa Malatji. Its Programming Logic and Design content follows the five-unit outline supplied for this project. Explanations and practice questions are original; the platform is not an official institutional course or assessment.</p><h2>Language and review</h2><p>This first release is in English. Reviewed Sepedi explanations and additional modules are planned. Teaching content and diagram behaviour should be reviewed before use in assessed work.</p><h2>Your progress and privacy</h2><p>Completed lesson IDs are saved in localStorage on this browser when available. They are not sent to a server or synchronised across devices. Reset progress removes these stored completion marks. Written practice tasks are self-checked against model solutions. The interactive exercises check selected answers and statement order, with two progressive hints and worked solutions unlocked after an attempt. Lesson answers, interactive-exercise progress, written drafts and editor code save in localStorage in this browser when available. Diagrams are generated locally. Tracer runtime inputs and execution history stay in page memory. Practice exam answers and self-assessed written marks save in this browser. A timed exam keeps its deadline when you leave the page; saved answers are submitted when the exam is open or next reopened after the deadline. Practice exams reuse the lesson quiz bank and are not secure assessments. Saved work does not sync across devices or identify individual students sharing one browser profile. Use Saved work to clear drafts and question progress on a shared device.</p><h2>Practice, not secure assessment</h2><p>Solutions are hidden in the interface until a complete attempt is submitted. Because this is a browser-only application, a determined user can inspect downloaded source files to find answers. It is not a secure examination system.</p><h2>Current boundaries</h2><p>The diagram lab supports a documented subset, not every pseudocode dialect. It validates structure but does not prove an algorithm correct. The interactive tracer runs documented variable, one-dimensional array and two-dimensional grid statements with typed input and execution limits. Guided array and sorting traces use fixed examples. Methods and classes are not executable in the tracer yet. There are no student accounts, lecturer dashboards or cross-device progress in this version.</p><h2>Contact</h2><p>Report a content or website issue to <a style="color:var(--purple);text-decoration:underline" href="mailto:lazylefa@gmail.com?subject=LogicLab%20feedback">lazylefa@gmail.com</a>.</p><a class="button" href="#home">Back to learning</a></div>`;sidebar();}
function route(){pageCleanup();pageCleanup=()=>{};document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');document.body.classList.remove('print-diagram');const[page,id]=location.hash.slice(1).split('/');if(page==='exams')pageCleanup=examPage({view,crumb,sidebar});else if(page==='unit')unitPage(id);else if(page==='lesson')lessonPage(id);else if(page==='resources')resourcesPage();else if(page==='activities')activitiesPage({view,crumb,sidebar});else if(page==='activity')activityPage({id,view,crumb,sidebar});else if(page==='tasks')tasksPage();else if(page==='task')taskPage(id);else if(page==='lab')labPage();else if(page==='trace')tracePage();else if(page==='trace-guided')guidedTracePage();else if(page==='saved-work')savedWorkPage();else if(page==='about')about();else dashboard();window.scrollTo({top:0,behavior:'instant'});document.title=(page==='lesson'?activeLesson?.title:page==='lab'?'Diagram lab':page==='trace'?'Interactive tracing':page==='trace-guided'?'Guided traces':page==='saved-work'?'Saved work':page==='exams'?'Practice exams':page==='resources'?'Study resources':page==='activities'?'Interactive exercises':page==='activity'?'Interactive exercise':page==='tasks'?'Practice tasks':page==='task'?'Practice task':'Programming Logic and Design')+' | LogicLab';const report=$('#report-content');if(report){report.href='mailto:lazylefa@gmail.com?'+new URLSearchParams({subject:'LogicLab content feedback',body:'Page: '+location.href+'\n\nWhat is unclear or incorrect?\n\nWhat did you expect?\n'}).toString();}$('#main').focus({preventScroll:true});}
$('#menu-toggle').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('#menu-toggle').setAttribute('aria-expanded',open);};document.addEventListener('keydown',event=>{if(event.key==='Escape'){document.body.classList.remove('menu-open');$('#menu-toggle').setAttribute('aria-expanded','false');}});$('#reset-progress').onclick=()=>$('#reset-dialog').showModal();$('#cancel-reset').onclick=()=>$('#reset-dialog').close();$('#confirm-reset').onclick=()=>{completed.clear();save();$('#reset-dialog').close();route();};window.addEventListener('hashchange',route);route();


